import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Navbar from '../components/navbar';
import StudentSidebar from '../components/StudentSidebar';
import Footer from '../components/footer';

const ViewTasks = () => {
  // State management
  const [milestones, setMilestones] = useState([]);
  const [tasks, setTasks] = useState({});
  const [group, setGroup] = useState(null);
  const [project, setProject] = useState(null);
  const [student, setStudent] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Form states
  const [newMilestone, setNewMilestone] = useState({
    title: '',
    dueDate: '',
    status: 'Pending'
  });

  const [newTask, setNewTask] = useState({
    title: '',
    status: 'Pending'
  });

  // Get current user from localStorage
  const user = JSON.parse(localStorage.getItem('user'));

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        setError(null);

        // 1. Get student details by user ID
        const studentRes = await axios.get(`http://localhost:5000/api/student/user/${user.id}`);
        const studentData = studentRes.data;
        setStudent(studentData);

        // 2. Check if student is grouped
        if (!studentData.isGrouped) {
          setError('You are not part of any group yet. Please join a group to view tasks.');
          setLoading(false);
          return;
        }

        // 3. Get group details by student regNo in request body
        const groupRes = await axios.post('http://localhost:5000/api/group/student', {
          regNo: studentData.regNo
        });
        const groupData = groupRes.data;
        setGroup(groupData);

        // 4. Get project details
        const projectRes = await axios.get(`http://localhost:5000/api/project/${groupData.projectID}`);
        setProject(projectRes.data);

        // 5. Get milestones for the group's project
        const milestonesRes = await axios.get(`http://localhost:5000/api/milestone/project/${groupData.projectID}`);
        setMilestones(milestonesRes.data);

        // 6. Get tasks for each milestone
        const tasksData = {};
        for (const milestone of milestonesRes.data) {
          try {
            const tasksRes = await axios.get(`http://localhost:5000/api/task/milestone/${milestone._id}`);
            tasksData[milestone._id] = tasksRes.data;
          } catch (err) {
            // If no tasks found, initialize empty array
            if (err.response?.status === 404) {
              tasksData[milestone._id] = [];
            } else {
              throw err;
            }
          }
        }
        setTasks(tasksData);

      } catch (err) {
        setError(err.response?.data?.message || 'Failed to fetch data. Please try again later.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [user.id]);

  const handleAddMilestone = async () => {
    if (!newMilestone.title.trim() || !newMilestone.dueDate) {
      alert('Please fill in all milestone fields.');
      return;
    }

    try {
      const milestoneData = {
        ...newMilestone,
        projectID: group.projectID
      };

      const res = await axios.post('http://localhost:5000/api/milestone', milestoneData);

      setMilestones([...milestones, res.data]);
      setTasks({ ...tasks, [res.data._id]: [] });
      setNewMilestone({ title: '', dueDate: '', status: 'Pending' });
    } catch (err) {
      alert(err.response?.data?.message || 'Failed to add milestone');
    }
  };

  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim()) {
      alert('Please enter a task title.');
      return;
    }

    try {
      const taskData = {
        ...newTask,
        milestoneId,
        uploadedBy: user.id
      };

      const res = await axios.post('http://localhost:5000/api/task', taskData);

      setTasks({
        ...tasks,
        [milestoneId]: [...(tasks[milestoneId] || []), res.data]
      });

      setNewTask({ title: '', status: 'Pending' });
    } catch (err) {
      alert(err.response?.data?.message || 'Failed to add task');
    }
  };

  const handleUpdateTaskStatus = async (milestoneId, taskId, newStatus) => {
    try {
      await axios.patch(`http://localhost:5000/api/task/${taskId}`, {
        status: newStatus,
        completedBy: student.studentName
      });

      setTasks(prevTasks => ({
        ...prevTasks,
        [milestoneId]: prevTasks[milestoneId].map(task => 
          task._id === taskId 
            ? { ...task, status: newStatus, completedBy: student.studentName } 
            : task
        )
      }));
    } catch (err) {
      alert(err.response?.data?.message || 'Failed to update task status');
    }
  };

  const handleDeleteTask = async (milestoneId, taskId) => {
    if (!window.confirm('Are you sure you want to delete this task?')) return;

    try {
      await axios.delete(`http://localhost:5000/api/task/${taskId}`);

      setTasks(prevTasks => ({
        ...prevTasks,
        [milestoneId]: prevTasks[milestoneId].filter(task => task._id !== taskId)
      }));
    } catch (err) {
      alert(err.response?.data?.message || 'Failed to delete task');
    }
  };

  if (loading) {
    return (
      <div className="tasks-container">
        <Navbar />
        <div className="content-wrapper">
          <StudentSidebar />
          <div className="main-content">
            <div className="loading-spinner">Loading...</div>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  if (error) {
    return (
      <div className="tasks-container">
        <Navbar />
        <div className="content-wrapper">
          <StudentSidebar />
          <div className="main-content">
            <div className="error-message">{error}</div>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  if (!group) {
    return (
      <div className="tasks-container">
        <Navbar />
        <div className="content-wrapper">
          <StudentSidebar />
          <div className="main-content">
            <div className="no-group-message">
              You are not part of any group yet. Please join a group to view tasks.
            </div>
          </div>
        </div>
        <Footer />
      </div>
    );
  }

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Project Tasks and Milestones</h1>

          {project && (
            <div className="project-info">
              <h2>{project.title}</h2>
              <p>Status: {project.status}</p>
            </div>
          )}

          {/* Add Milestone Section */}
          <div className="milestone-form">
            <h3>Add New Milestone</h3>
            <div className="form-group">
              <label>Title:</label>
              <input
                type="text"
                value={newMilestone.title}
                onChange={(e) => setNewMilestone({...newMilestone, title: e.target.value})}
                placeholder="Milestone title"
              />
            </div>
            <div className="form-group">
              <label>Due Date:</label>
              <input
                type="date"
                value={newMilestone.dueDate}
                onChange={(e) => setNewMilestone({...newMilestone, dueDate: e.target.value})}
              />
            </div>
            <div className="form-group">
              <label>Status:</label>
              <select
                value={newMilestone.status}
                onChange={(e) => setNewMilestone({...newMilestone, status: e.target.value})}
              >
                <option value="Pending">Pending</option>
                <option value="In Progress">In Progress</option>
                <option value="Completed">Completed</option>
              </select>
            </div>
            <button 
              className="add-button"
              onClick={handleAddMilestone}
            >
              Add Milestone
            </button>
          </div>

          {/* List of Milestones */}
          <div className="milestones-list">
            {milestones.length === 0 ? (
              <p className="no-milestones">No milestones yet. Add your first milestone above.</p>
            ) : (
              milestones.map((milestone) => (
                <div key={milestone._id} className="milestone-card">
                  <div className="milestone-header">
                    <h3>{milestone.title}</h3>
                    <div className="milestone-meta">
                      <span>Due: {new Date(milestone.dueDate).toLocaleDateString()}</span>
                      <span className={`status-badge ${milestone.status.toLowerCase().replace(' ', '-')}`}>
                        {milestone.status}
                      </span>
                    </div>
                  </div>

                  {/* Add Task Section */}
                  <div className="task-form">
                    <h4>Add New Task</h4>
                    <div className="form-row">
                      <input
                        type="text"
                        value={newTask.title}
                        onChange={(e) => setNewTask({...newTask, title: e.target.value})}
                        placeholder="Task title"
                      />
                      <select
                        value={newTask.status}
                        onChange={(e) => setNewTask({...newTask, status: e.target.value})}
                      >
                        <option value="Pending">Pending</option>
                        <option value="In Progress">In Progress</option>
                        <option value="Completed">Completed</option>
                      </select>
                      <button 
                        className="add-button small"
                        onClick={() => handleAddTask(milestone._id)}
                      >
                        Add Task
                      </button>
                    </div>
                  </div>

                  {/* Tasks List */}
                  <div className="tasks-list">
                    {tasks[milestone._id]?.length > 0 ? (
                      <table>
                        <thead>
                          <tr>
                            <th>Task</th>
                            <th>Status</th>
                            <th>Completed By</th>
                            <th>Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {tasks[milestone._id].map((task) => (
                            <tr key={task._id}>
                              <td>{task.title}</td>
                              <td>
                                <span className={`status-badge ${task.status.toLowerCase().replace(' ', '-')}`}>
                                  {task.status}
                                </span>
                              </td>
                              <td>{task.completedBy || "N/A"}</td>
                              <td className="actions">
                                {task.status !== "Completed" && (
                                  <button
                                    className="action-button complete"
                                    onClick={() => handleUpdateTaskStatus(milestone._id, task._id, "Completed")}
                                  >
                                    Mark Complete
                                  </button>
                                )}
                                <button
                                  className="action-button delete"
                                  onClick={() => handleDeleteTask(milestone._id, task._id)}
                                >
                                  Delete
                                </button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    ) : (
                      <p className="no-tasks">No tasks for this milestone yet.</p>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
